//! The starter component library (starter.js, one for one): about thirty everyday things built from simple solids by
//! the kernel when picked — each part a group of its own inside the component, in metres, standing on z = 0 (or
//! lying on it for wall things, front toward blue). `build_starter(model, id, name)` makes the component definition
//! (call inside `Model::change`). Spec gap: the 0.5 entourage items (`ent-*`, generated by lib/entourage) are not in
//! this port yet; `build_starter` returns None for them, as for any unknown id.

use cc_m3d::mesh::mesh_def;
use cc_m3d::model::{Model, place};
use cc_m3d::ops::{add_polygon, ngon_pts, push_pull, rect_pts};
use cc_m3d::paint::paint_faces;
use cc_m3d::vec::{IDENT, M4, P3};
use cc_m3d::{Error, Res};
use serde_json::{Value, json};

use crate::i18n::t0;

